// Declarative side-panel cards. A subsystem describes its cards; this builds the DOM (textContent only) and returns handles.
// Card: { label, badge?: { id, text }, only?: "model" | "photo", items: [widget] }. Widgets (one key each, plus optional `only`):
//   readouts: [{ id, label, unit, value }]          → ui.set(id, text)
//   trace: { id, series: [{ token, min, max }], span, top, bottom, aria }   → ui.trace(id).push(t, [v…]) / .draw(t)
//   buttons: [{ id, label, toggle?: [onLabel, offLabel], pressed?, onClick(pressed) }]   → ui.toggle(id).set(bool)
//   slider: { id, label, min, max, step, value, onInput(v) }   → ui.slider(id).set(v)
//   meter: { id }  → ui.meter(id).set(0..1, hot)        cells: { id, labels }  → ui.cells(id).set(i, text, on)
//   legend: [[token, name]]   key: [[token, text]]   svg: { id, viewBox, aria }  → ui.el(id)   text: "…"   list: ["…"]
// Text arrives already translated (subsystems use ctx.t); readout values are written with the local decimal mark.
// Element ids are `${scope}-${id}`: scope defaults to the component id; pages with several cars pass one per car.
import { num } from "./i18n.js";
import { h } from "./dom.js";

export function createPanel(container, compId, scope = compId) {
  const els = new Map(), api = {};
  const key = id => `${scope}-${id}`;

  const widgets = {
    readouts: items => h("div", { class: "readouts" }, items.map(r => {
      const o = h("output", { id: key(r.id) }, r.value == null ? "–" : num(r.value)); els.set(r.id, o);
      return h("div", {}, h("small", {}, r.label), o, h("small", {}, r.unit ?? ""));
    })),
    trace: t => {
      const svg = h("svg:svg", { viewBox: "0 0 280 110", role: "img", "aria-label": t.aria ?? "" });
      const grid = [[55, null], [5, "2 3"], [105, "2 3"]].map(([y, dash]) => h("svg:line", { x1: 0, y1: y, x2: 280, y2: y, stroke: "var(--rule)", "stroke-dasharray": dash }));
      const lines = t.series.map(s => h("svg:polyline", { fill: "none", stroke: `var(${s.token})`, "stroke-width": 1.6 }));
      svg.append(...grid, ...lines, h("svg:text", { x: 278, y: 15, "text-anchor": "end" }, t.top ?? ""), h("svg:text", { x: 278, y: 101, "text-anchor": "end" }, t.bottom ?? ""));
      const buf = [], span = t.span ?? 6;
      els.set(t.id, {
        push(time, values) { buf.push({ time, values }); },
        draw(now) {
          while (buf.length && buf[0].time < now - span) buf.shift();
          const X = tt => ((tt - (now - span)) / span * 280).toFixed(1);
          t.series.forEach((s, i) => lines[i].setAttribute("points", buf.map(p => {
            const v = Math.max(s.min, Math.min(s.max, p.values[i]));
            return `${X(p.time)},${(105 - (v - s.min) / (s.max - s.min) * 100).toFixed(1)}`;
          }).join(" ")));
        },
      });
      return h("div", { class: "trace" }, svg);
    },
    buttons: items => h("div", { class: "row" }, items.map(b => {
      // toggle: [onLabel, offLabel] flips itself; pressed without toggle = radio-style button whose state the caller sets.
      const el = h("button", { type: "button", "aria-pressed": b.toggle || b.pressed != null ? String(!!b.pressed) : null }, b.toggle ? b.toggle[b.pressed ? 0 : 1] : b.label);
      const handle = { el, pressed: !!b.pressed, set(p) { handle.pressed = p; el.setAttribute("aria-pressed", String(p)); if (b.toggle) el.textContent = b.toggle[p ? 0 : 1]; } };
      el.addEventListener("click", () => { if (b.toggle) handle.set(!handle.pressed); b.onClick?.(handle.pressed); });
      els.set(b.id, handle);
      return el;
    })),
    slider: s => {
      const input = h("input", { id: key(s.id), type: "range", min: s.min, max: s.max, step: s.step ?? 1, value: s.value });
      input.addEventListener("input", () => s.onInput?.(+input.value));
      els.set(s.id, { el: input, set(v) { input.value = v; } });
      return h("div", { class: "slider" }, h("label", { class: "label", for: key(s.id) }, s.label), input);
    },
    meter: m => { const bar = h("i"), el = h("div", { class: "meter" }, bar); els.set(m.id, { set(f, hot) { bar.style.width = `${(Math.max(0, Math.min(1, f)) * 100).toFixed(0)}%`; el.classList.toggle("hot", !!hot); } }); return el; },
    cells: c => {
      const cells = c.labels.map(l => h("div", { class: "cyl" }, h("b", {}, l), h("span", {}, "–")));
      els.set(c.id, { set(i, text, on) { const el = cells[i]; if (el.dataset.s !== text) { el.dataset.s = text; el.lastChild.textContent = text; } el.classList.toggle("power", !!on); } });
      return h("div", { class: "cyls", style: `--n:${Math.min(c.labels.length, 4)}` }, cells);
    },
    legend: items => h("ul", { class: "legend" }, items.map(([tok, name]) => h("li", {}, h("span", { class: "sw", style: `background:var(${tok})` }), name))),
    key: items => h("div", { class: "key" }, items.map(([tok, text]) => h("span", {}, h("i", { style: `background:var(${tok})` }), text))),
    svg: s => { const el = h("svg:svg", { viewBox: s.viewBox, role: "img", "aria-label": s.aria ?? "", class: "diagram" }); els.set(s.id, el); return el; },
    text: t => h("p", { class: "note" }, t),
    list: items => h("ul", { class: "talk" }, items.map(t => h("li", {}, t))),
  };

  // Append cards; returns the shared handle API (call again to add more cards for the same component).
  return function cards(list) {
    for (const card of list) {
      const label = h("div", { class: "label" }, card.label ?? "");
      if (card.badge) { const b = h("span", { class: "badge" }, card.badge.text); label.append(" · ", b); els.set(card.badge.id, { set(text, on) { b.textContent = text; b.classList.toggle("on", !!on); } }); }
      const el = h("div", { class: "panel", "data-comp": compId, "data-only": card.only }, label);
      for (const w of card.items ?? []) {
        const [type] = Object.keys(w).filter(k => k !== "only");
        const node = widgets[type](w[type]);
        if (w.only) node.dataset.only = w.only;
        el.append(node);
      }
      container.append(el);
    }
    return Object.assign(api, {
      set: (id, text) => { els.get(id).value = num(text); },
      el: id => els.get(id), trace: id => els.get(id), toggle: id => els.get(id), slider: id => els.get(id),
      meter: id => els.get(id), cells: id => els.get(id), badge: id => els.get(id),
    });
  };
}
// DOM building shared by the pages: text only (textContent), never HTML strings.
const SVG = "http://www.w3.org/2000/svg";

// h("div", { class: "x" }, child, [children], "text"): attributes null/false are left out, true is set empty; "svg:tag" makes SVG.
export function h(tag, attrs = {}, ...kids) {
  const el = tag.startsWith("svg:") ? document.createElementNS(SVG, tag.slice(4)) : document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) if (v != null && v !== false) el.setAttribute(k, v === true ? "" : v);
  for (const k of kids.flat()) if (k != null) el.append(k);
  return el;
}

// A link; one leaving the site opens in a new tab.
export const link = (href, text) => h("a", { href, target: href.startsWith("http") ? "_blank" : null, rel: href.startsWith("http") ? "noopener" : null }, text);
// Page language. lang.js picks it before first paint and sets <html lang>; this module reads it. English is the source:
// t("English text", ...args) looks the text up in lib/app/i18n/<lang>.js (keyed by the English, first argument always a
// "double-quoted" literal so tests can find it), fills {0}, {1}… with args and writes numeric args the local way.
// Car text is translated per stop in stops/<slug>/<lang>.js: car.js's shape, strings only, merged over it by loadCar.
export const LANGS = ["en", "hu"];
const STORE = "tour-lang";   // also read by lang.js
export const lang = LANGS.includes(globalThis.document?.documentElement.lang) ? document.documentElement.lang : "en";
const catalog = lang === "en" ? null : (await import(`./i18n/${lang}.js`)).default;
export const missing = new Set();   // keys with no translation; ?debug exposes them and the e2e tests check it is empty

// A number (as toFixed gives it) written the local way: decimal comma in Hungarian. Other text passes unchanged.
export const num = v => (lang !== "en" && /^[-−]?\d+\.\d+$/.test(String(v)) ? String(v).replace(".", ",") : String(v));

export function t(text, ...args) {
  let out = text;
  if (catalog) { out = catalog[text]; if (out === undefined) { missing.add(text); out = text; } }
  return args.length ? out.replace(/\{(\d)\}/g, (_, i) => num(args[i])) : out;
}

// Overlay a translation on a car config: objects key by key, arrays item by item; null or a missing item keeps the original.
export function merge(base, over) {
  if (over == null) return base;
  if (Array.isArray(base) && Array.isArray(over)) return base.map((b, i) => merge(b, over[i]));
  if (base && typeof base === "object" && !Array.isArray(base) && typeof over === "object" && !Array.isArray(over)) {
    const out = { ...base };
    for (const k of Object.keys(over)) out[k] = merge(base[k], over[k]);
    return out;
  }
  return over;
}

// slug must already be checked against stops/tour.js.
export async function loadCar(slug) {
  const car = (await import(`../../stops/${slug}/car.js`)).default;
  return lang === "en" ? car : merge(car, (await import(`../../stops/${slug}/${lang}.js`)).default);
}

// Static page text (elements marked data-i18n hold their English text as the key) and the EN/HU switch in the header bar.
export function localizePage() {
  for (const el of document.querySelectorAll("[data-i18n]")) el.textContent = t(el.textContent.trim().replace(/\s+/g, " "));
  document.documentElement.classList.remove("translating");
  for (const b of document.querySelectorAll("[data-lang]")) {
    b.setAttribute("aria-pressed", String(b.dataset.lang === lang));
    b.addEventListener("click", () => {
      if (b.dataset.lang === lang) return;
      try { localStorage.setItem(STORE, b.dataset.lang); } catch { /* storage blocked: the reload falls back to the default */ }
      location.reload();
    });
  }
}
/* Layout shared by the index and every stop, after the current mercedes-benz.com pages: black header bar and hero, white
   page, condensed serif headlines, black photo cards with 12 px corners, pill buttons. Light by default, dark on request.
   Colours are tokens and the 3-D scene reads them too; --band and --card are the fixed-black areas. */
/* Instrument Serif (SIL OFL 1.1, fonts/OFL.txt), standing in for the brand's proprietary condensed serif. Two subsets, as
   Google Fonts splits it: latin-ext carries Hungarian ő and ű and loads only on pages that use them. */
@font-face {
  font-family: "Instrument Serif"; font-weight: 400; font-style: normal; font-display: swap;
  src: url("fonts/instrument-serif-latin-400.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F,
    U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}
@font-face {
  font-family: "Instrument Serif"; font-weight: 400; font-style: normal; font-display: swap;
  src: url("fonts/instrument-serif-latin-ext-400.woff2") format("woff2");
  unicode-range: U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF,
    U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C4, U+2113, U+2C60-2C7F, U+A720-A7FF;
}
:root {
  --bg: #ffffff; --panel: #f4f4f4; --fg: #333333; --muted: #696969; --rule: #e8e8e8; --edge: #9f9f9f;
  --accent: #0078d6; --stage: #ececec;
  --band: #000000; --band-fg: #ffffff; --band-muted: #bbbbbb; --band-edge: #696969; --card: #000000;
  --l1: #d9480f; --l2: #e8a317; --l3: #2b8a3e; --l4: #1c64c4; --l5: #8e44ad;
  --metal: #8a96a1; --warn: #c92a2a;
  --cfd-1: #2b3fa0; --cfd-2: #2c9be0; --cfd-3: #5fd068; --cfd-4: #f2c230; --cfd-5: #d8341e;   /* wind-tunnel colour field, both themes */
  --display: "Instrument Serif", ui-serif, Georgia, "Times New Roman", serif;
  --body: -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --gutter: clamp(16px, 4vw, 40px); --max: 1320px; --radius: 12px;
  color-scheme: light;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #000000; --panel: #161616; --fg: #ffffff; --muted: #a3a3a3; --rule: #333333; --edge: #696969;
    --stage: #111111; --card: #161616;
    --l1: #ff7a45; --l2: #f5c242; --l3: #5cc46f; --l4: #5b9bf0; --l5: #b77fd6; --metal: #6f7c87; --warn: #ff6b6b;
    color-scheme: dark;
  }
}
:root[data-theme="dark"] {
  --bg: #000000; --panel: #161616; --fg: #ffffff; --muted: #a3a3a3; --rule: #333333; --edge: #696969;
  --stage: #111111; --card: #161616;
  --l1: #ff7a45; --l2: #f5c242; --l3: #5cc46f; --l4: #5b9bf0; --l5: #b77fd6; --metal: #6f7c87; --warn: #ff6b6b;
  color-scheme: dark;
}
[hidden] { display: none !important; }
* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body { margin: 0; background: var(--bg); color: var(--fg); font-family: var(--body); font-size: 16px; line-height: 1.55; letter-spacing: .2px; -webkit-font-smoothing: antialiased; }
a { color: inherit; text-decoration-color: var(--edge); text-underline-offset: 3px; }
.wrap {
  max-width: var(--max); margin: 0 auto; display: grid; gap: 32px;
  padding: 40px max(var(--gutter), env(safe-area-inset-right)) max(56px, env(safe-area-inset-bottom)) max(var(--gutter), env(safe-area-inset-left));
}
.eyebrow { font-size: 14px; color: var(--muted); }
h1 { font-family: var(--display); font-weight: 400; font-size: clamp(40px, 5.6vw, 64px); line-height: 1.1; margin: 6px 0 16px; text-wrap: balance; letter-spacing: 0; }
h2 { font-family: var(--display); font-weight: 400; font-size: 28px; line-height: 1.2; margin: 0 0 12px; text-wrap: balance; letter-spacing: 0; }
.lede { max-width: 62ch; font-size: 18px; margin: 0; }

/* Black header bar: the page's own link on the left, where-am-I on the right. Static in index.html and stop.html. */
.bar { background: var(--band); color: var(--band-muted); padding: env(safe-area-inset-top) max(var(--gutter), env(safe-area-inset-right)) 0 max(var(--gutter), env(safe-area-inset-left)); }
.crumbs { max-width: calc(var(--max) - 2 * var(--gutter)); margin: 0 auto; min-height: 64px; display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 0 16px; font-size: 14px; }
.crumbs a, .crumbs .home { display: inline-flex; align-items: center; min-height: 44px; color: var(--band-fg); text-decoration: none; }
.crumbs .home { font-family: var(--display); font-size: 24px; letter-spacing: 0; }
.crumbs a:hover { text-decoration: underline; }
.crumbs .where { flex: 1; text-align: center; }
@media (max-width: 600px) { .crumbs .where { order: 3; flex-basis: 100%; text-align: left; padding-bottom: 12px; } .crumbs .where:empty { display: none; } }
.langs { display: inline-flex; gap: 2px; padding: 2px; border: 1px solid var(--band-edge); border-radius: 9999px; }
.langs button { min-height: 36px; min-width: 44px; padding: 0 12px; font-size: 13px; color: var(--band-fg); border-color: transparent; }
.langs button[aria-pressed="true"] { background: var(--band-fg); border-color: var(--band-fg); color: var(--band); }
.translating [data-i18n] { visibility: hidden; }   /* lang.js sets it; i18n.js removes it once the text is translated */
.pager { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 8px 24px; border-top: 1px solid var(--rule); padding-top: 16px; }
.pager a { display: inline-flex; align-items: center; min-height: 44px; font-family: var(--display); font-size: 24px; letter-spacing: 0; text-decoration: none; }
.pager a:hover { text-decoration: underline; }

/* Pill buttons: 44 px targets, no double-tap zoom. Selected = filled, like the site's brand switcher. */
button, .pill { display: inline-flex; align-items: center; justify-content: center; font: 700 14px/1.2 var(--body); letter-spacing: .2px; color: var(--fg); background: transparent; border: 1px solid var(--edge); border-radius: 9999px; padding: 10px 20px; min-height: 44px; cursor: pointer; touch-action: manipulation; text-decoration: none; }
button[aria-pressed="true"] { background: var(--fg); border-color: var(--fg); color: var(--bg); }
.pill.primary { background: var(--accent); border-color: var(--accent); color: var(--band-fg); }
button:focus-visible, input:focus-visible, a:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.label { font-size: 13px; color: var(--muted); }

/* Stage (viewer.js): keeps the museum photo's aspect so the overlay lines up; the story layout below sizes it to leave room
   for scrolling past the touch-locked stage. */
.stage {
  --ar: 1.4944; position: relative; background: var(--stage); border-radius: var(--radius);
  aspect-ratio: var(--aspect, 1200 / 803); width: min(100%, calc((100svh - 32px) * var(--ar))); justify-self: center;
  overflow: hidden; touch-action: none; -webkit-user-select: none; user-select: none;
}
.stage img, .stage canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.stage img { filter: brightness(.72) saturate(.85); }
.stage .hint { position: absolute; left: 14px; bottom: 10px; font-size: 12px; color: var(--muted); pointer-events: none; }
.stage .credit { position: absolute; right: 10px; bottom: 8px; font-size: 10px; color: #f1f3f5; background: rgba(0,0,0,.55); padding: 2px 8px; border-radius: 9999px; }
.stage .credit a { color: inherit; }
.stage .fail { position: absolute; inset: 0; margin: 0; padding: 16px; }
.panel { background: var(--panel); border-radius: var(--radius); padding: 20px; display: grid; gap: 12px; min-width: 0; }
.readouts { display: grid; grid-template-columns: repeat(2, 1fr); gap: 14px 8px; }
.readouts div { display: grid; gap: 1px; }
.readouts output { font: 300 24px/1.2 var(--body); font-variant-numeric: tabular-nums; }
.readouts small { font-size: 12px; color: var(--muted); }
.row { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.slider { display: grid; gap: 4px; }
input[type=range] { width: 100%; min-height: 32px; accent-color: var(--accent); }
.trace svg, svg.diagram { width: 100%; height: auto; display: block; }
.trace text, svg.diagram text { font-family: var(--mono); font-size: 9px; fill: var(--muted); }
.key { display: flex; gap: 14px; flex-wrap: wrap; font-size: 12px; color: var(--muted); }
.key i { display: inline-block; width: 14px; height: 3px; vertical-align: middle; margin-right: 5px; }
.legend { list-style: none; margin: 0; padding: 0; display: grid; gap: 4px; font-size: 14px; }
.legend li { display: grid; grid-template-columns: 12px 1fr; gap: 10px; align-items: center; }
.legend .sw { width: 12px; height: 12px; border-radius: 3px; }
.cyls { display: grid; grid-template-columns: repeat(var(--n, 4), minmax(0, 1fr)); gap: 6px; }
.cyl { border: 1px solid var(--rule); border-radius: 8px; padding: 6px 2px; display: grid; gap: 2px; text-align: center; min-width: 0; background: var(--bg); }
.cyl b { font-family: var(--mono); font-size: 11px; color: var(--muted); font-weight: 500; }
.cyl span { font-size: 11.5px; font-weight: 600; hyphens: auto; overflow-wrap: break-word; }
.cyl.power { border-color: var(--l1); box-shadow: inset 0 -3px 0 var(--l1); }
.badge { display: inline-block; font-size: 12px; padding: 1px 10px; border: 1px solid var(--edge); border-radius: 9999px; color: var(--muted); }
.badge.on { background: var(--l1); border-color: var(--l1); color: var(--bg); }
.meter { height: 6px; background: var(--rule); border-radius: 3px; overflow: hidden; }
.meter i { display: block; height: 100%; width: 0; background: var(--accent); }
.meter.hot i { background: var(--l1); }
.talk { margin: 0; padding-left: 18px; display: grid; gap: 8px; font-size: 15px; }
.note { font-size: 13px; color: var(--muted); margin: 0; }
footer { display: grid; gap: 10px; font-size: 14px; color: var(--muted); border-top: 1px solid var(--rule); padding-top: 24px; }
footer summary { cursor: pointer; min-height: 32px; color: var(--fg); }
footer ul { margin: 4px 0 0; padding-left: 18px; }
.fail { color: var(--warn); }

/* Index hero: a full-bleed museum photo with the title over its dark left side; on phones the photo sits above the text
   and fades into the black band, as the site's own mobile hero does. */
.hero { position: relative; overflow: hidden; background: var(--band); color: var(--band-fg); display: grid; align-items: center; min-height: min(640px, 80svh); }
.hero img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; object-position: 60% 50%; }
.hero::after { content: ""; position: absolute; inset: 0; background: linear-gradient(to right, var(--band) 0%, color-mix(in srgb, var(--band) 65%, transparent) 38%, transparent 70%); }
.hero .copy {
  position: relative; z-index: 1; width: 100%; max-width: var(--max); margin: 0 auto;
  padding: 56px max(var(--gutter), env(safe-area-inset-right)) 64px max(var(--gutter), env(safe-area-inset-left));
}
.hero .copy > * { max-width: 560px; }
.hero .eyebrow, .hero .status { color: var(--band-muted); }
.hero h1 { font-size: clamp(44px, 5.6vw, 72px); }
.hero .pill { margin-top: 32px; }
@media (max-width: 700px) {
  .hero { display: block; min-height: 0; text-align: center; }
  .hero img { position: relative; height: auto; aspect-ratio: 3 / 2; }
  .hero::after { inset: 0 0 auto; aspect-ratio: 3 / 2; background: linear-gradient(to top, var(--band) 0%, transparent 45%); }
  .hero .copy { margin-top: -40px; padding-top: 0; padding-bottom: 48px; }
  .hero .copy > * { margin-left: auto; margin-right: auto; }
}
.status { font-size: 14px; color: var(--muted); margin: 20px 0 0; }
.status::before { content: ""; display: inline-block; width: 8px; height: 8px; border-radius: 50%; background: var(--band-edge); margin-right: 8px; vertical-align: 1px; }
.status.ready::before { background: var(--l3); }

/* Index route: one section per room, black photo cards whose picture fades into the card under the title. */
.route { list-style: none; margin: 0; padding: 0; display: grid; gap: 72px; }
.room-head { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 4px 16px; margin-bottom: 28px; }
.room h2 { font-size: clamp(36px, 4.4vw, 48px); margin: 0; }
.room-head span { font-size: 14px; color: var(--muted); }
.stops { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 320px), 1fr)); gap: 40px; }
.stop a { display: flex; flex-direction: column; height: 100%; background: var(--card); color: var(--band-fg); border-radius: var(--radius); overflow: hidden; text-decoration: none; }
.stop a:focus-visible { outline-offset: 4px; }
.stop .pic { position: relative; aspect-ratio: 3 / 2; overflow: hidden; }
.stop .pic::after { content: ""; position: absolute; inset: 0; background: linear-gradient(to top, var(--card) 0%, transparent 45%); }
.stop img { width: 100%; height: 100%; object-fit: cover; display: block; transition: transform .7s cubic-bezier(.2, .6, .2, 1); }
.stop .text { position: relative; flex: 1; display: flex; flex-direction: column; align-items: flex-start; gap: 10px; padding: 0 24px 24px; margin-top: -28px; }
.stop small { font-size: 12px; color: var(--band-fg); border: 1px solid var(--band-edge); border-radius: 4px; padding: 2px 8px; }
.stop b { font-family: var(--display); font-weight: 400; font-size: 32px; line-height: 1.15; letter-spacing: 0; }
.stop .text > p { margin: 0 0 8px; font-size: 15px; color: var(--band-muted); }
.stop .pill { margin-top: auto; text-align: left; }
.stop .pill i { font-style: normal; margin-left: 8px; transition: transform .3s; }
@media (hover: hover) {
  .stop a:hover img { transform: scale(1.04); }
  .stop a:hover .pill i { transform: translateX(4px); }
}
@media (prefers-reduced-motion: reduce) { .stop img, .stop .pill i { transition: none; } }

/* Scroll stories (story.js: every stop page, the teaser): each car's stage pins while its steps scroll past, above them on a
   phone held upright and beside them otherwise. The step at the reading line is the one on the stage; the others are dimmed. */
.stories { display: grid; gap: 96px; }
.story-stage { position: sticky; top: 0; z-index: 1; background: var(--bg); padding: max(12px, env(safe-area-inset-top)) 0 12px; }
.story .stage { width: min(100%, calc(45svh * var(--ar))); margin-inline: auto; }
.step { min-height: 60svh; padding: 32px 0; display: grid; gap: 16px; align-content: start; transition: opacity .3s; }
.step:not(.on) { opacity: .4; }
.step h1, .step h2 { font-size: clamp(36px, 4.4vw, 48px); margin: 0; }
.step h3 { font-family: var(--display); font-weight: 400; font-size: 32px; line-height: 1.15; letter-spacing: 0; margin: 0; color: var(--fg); }
.step footer .pill { justify-self: start; margin-top: 8px; }
@media (orientation: landscape) and (min-width: 600px) {
  .story { display: grid; grid-template-columns: minmax(0, 1fr) clamp(280px, 32vw, 400px); gap: 32px; align-items: start; }
  .story-stage { height: 100svh; display: grid; place-items: center; padding: 16px 0; background: none; }
  .story .stage { width: min(100%, calc((100svh - 32px) * var(--ar))); }
  .step { min-height: 70svh; }
}
@media (prefers-reduced-motion: reduce) { .step { transition: none; } }

