      { pts: [[-1760, 730], [-1900, 1200], [-3250, 1215], [-3850, 760]], y: [-730, 730] },                                // soft top and windscreen
      { pts: [[600, -230], [430, 250], [180, 490], [-200, 500], [-620, 290], [-1250, -60], [-1500, -140], [-2830, -140],   // wings + running board
