  const group = new THREE.Group(); group.position.set(...(p.offset ?? [0, 0, 0.12])); carRoot.add(group);
  const caseMat = glass(0x8fa3b3, 0.12), caseEdge = line(0x8fa3b3, 0.6), pipeMat = glass(0x8fa3b3, 0.2);
