  const crank = new THREE.Group(); crank.position.set(0, 0, BL.crankZ); group.add(crank);
  crank.add(place(rod(gearMat, 0.03), V(-0.24, 0, 0), V(BL.blockX1 - 0.05, 0, 0)));
  for (let i = 0; i < n; i++) {
