    const d = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.06, 0.004), stage.tokenMat("--muted")); d.position.set(0, -1.1, m(p.ground ?? 0) + 0.002); d.userData.s = i / 10; group.add(d); return d;
