1	// Tubular space frame under a twisting load: one front wheel is lifted, the rear is held, as when a car crosses a kerb at
2	// an angle. Tubes are coloured by force (tension, compression) and the bending is drawn hugely exaggerated. Compare the
3	// 300 SL frame, whose side trusses run deep through the door area (so the doors had to open upwards), with the same frame
4	// cut down to a low sill for ordinary doors.
5	// Params (mm, ground at z = 0): label, stations, bays (lib/model/truss.js; door: "high" marks the door bays), EA (N),
6	// load (N at the front-left corner), exaggerate (× displacement), modes { high, low } (button labels), compare? (label
7	// of the stiffness-ratio readout: "high" is the reference).
8	import * as THREE from "three";
9	import { V, rod, place, ball } from "../lib/scene/helpers.js";
10	import { tubeFrame, twistTest } from "../lib/model/truss.js";
11	
12	export function create(ctx, p) {
13	  const { stage, carRoot, t } = ctx;
14	  const group = new THREE.Group(); carRoot.add(group);
15	  const tens = stage.tokenMat("--l1"), comp = stage.tokenMat("--l4"), idle = stage.tokenMat("--metal");
16	  const solve = door => {
17	    const f = tubeFrame(p.stations, p.bays.map(b => (b.door ? { ...b, door } : b)), p.EA), r = twistTest(f, 0, p.stations.length - 1, p.load);
18	    const maxF = Math.max(...r.forces.map(Math.abs)), base = f.nodes.map(n => V(n[0] / 1000, n[1] / 1000, n[2] / 1000));
19	    const tubes = f.members.map((mb, i) => {
20	      const F = r.forces[i], t = rod(Math.abs(F) < 0.06 * maxF ? idle : F > 0 ? tens : comp, mb.tag.startsWith("door") ? 0.009 : 0.007);
21	      group.add(t); return { t, ends: mb.ends };
22	    });
23	    return { ...r, f, maxF, base, tubes };
24	  };
25	  const modes = { high: solve("high"), low: solve("low") };
26	
27	  // Load arrow at the lifted corner, small balls where the frame is held.
28	  const nodeOf = (s, side, lv) => s * 6 + side * 3 + lv, last = p.stations.length - 1;
29	  const lift = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.16, 16), stage.tokenMat("--l2")); lift.rotation.x = Math.PI / 2; group.add(lift);
30	  const liftRod = rod(stage.tokenMat("--l2"), 0.015); group.add(liftRod);
31	  const supports = [nodeOf(last, 0, 0), nodeOf(last, 1, 0), nodeOf(0, 1, 0)].map(n => { const b = ball(stage.tokenMat("--muted"), 0.035); group.add(b); return { b, n }; });
32	
33	  let mode = "high", clock = 0, playing = !ctx.reducedMotion, f = 0.5;
34	  const ui = ctx.panel([{ label: p.label, items: [
35	    { buttons: [{ id: "high", label: p.modes.high, pressed: true, onClick: () => setMode("high") }, { id: "low", label: p.modes.low, pressed: false, onClick: () => setMode("low") }] },
36	    { readouts: [{ id: "load", label: t("Lift at the front wheel"), unit: t("N") }, { id: "twist", label: t("Frame twist"), unit: t("deg") },
37	      { id: "stiff", label: t("Twist stiffness"), unit: t("N·m per degree") }, { id: "rel", label: p.compare ?? t("Compared with the 300 SL frame"), unit: "%" },
38	      { id: "maxF", label: t("Hardest-working tube"), unit: t("N") }] },
39	    { buttons: [{ id: "play", toggle: [t("Pause"), t("Play")], pressed: playing, onClick: v => (playing = v) }] },
40	    { key: [["--l1", t("tube in tension")], ["--l4", t("in compression")], ["--metal", t("hardly loaded")], ["--l2", t("lift")], ["--muted", t("held")]] },
41	    { text: t("Bending drawn {0}× larger than it is. Tube sizes and frame shape are simplified.", p.exaggerate) },
42	  ] }]);
43	  function setMode(md) { mode = md; ui.toggle("high").set(md === "high"); ui.toggle("low").set(md === "low"); }
44	
45	  const q = V(0, 0, 0), a = V(0, 0, 0), b = V(0, 0, 0);
46	  const posOf = (s, n, out) => out.copy(s.base[n]).addScaledVector(q.set(...s.u[n]).multiplyScalar(1 / 1000), p.exaggerate * f);
47	  return {
48	    layout({ active }) { group.visible = active; },
49	    update(dt) {
50	      if (playing) { clock += dt; f = 0.5 - 0.5 * Math.cos(clock * 1.4); }
51	      for (const [k, s] of Object.entries(modes)) for (const tb of s.tubes) {
52	        tb.t.visible = k === mode;
53	        if (k === mode) place(tb.t, posOf(s, tb.ends[0], a), posOf(s, tb.ends[1], b).clone());
54	      }
55	      const s = modes[mode], corner = posOf(s, nodeOf(0, 0, 0), a);
56	      lift.position.copy(corner).add(q.set(0, 0, -0.12)); place(liftRod, corner.clone().add(q.set(0, 0, -0.42)), corner.clone().add(q.set(0, 0, -0.14)));
57	      for (const sp of supports) posOf(s, sp.n, sp.b.position).add(q.set(0, 0, -0.04));
58	      ui.set("load", (p.load * f).toFixed(0)); ui.set("twist", (s.twist * f).toFixed(3));
59	      ui.set("stiff", s.stiffness.toFixed(0)); ui.set("rel", (s.stiffness / modes.high.stiffness * 100).toFixed(0));
60	      ui.set("maxF", (s.maxF * f).toFixed(0));
61	    },
62	  };
63	}
